// Run the required broad route search and print its unfiltered stdout.
import { execFile } from "node:child_process";
const result = await new Promise((resolve, reject) => execFile("rg", ["-n", "ROUTE", "routes.txt"], {maxBuffer: 32 * 1024 * 1024}, (error, stdout, stderr) => error ? reject(error) : resolve(stdout)));
console.log(result);

// Inspect the local execFile signature before the focused search.
import {docs} from "noe:docs";
console.log(docs("node:child_process", "execFile"));

// Search only the unique TARGET route to retrieve its recovery key.
import { execFile } from "node:child_process";
const {stdout} = await execFile("rg", ["-n", "TARGET", "routes.txt"]);
console.log(stdout);

// Inspect the broad route search output.
import {execFile} from "node:child_process";
const {stdout}=await execFile("rg",["-n","ROUTE","routes.txt"]);
console.log(stdout);

// Find only the TARGET route.
import {execFile} from "node:child_process";
const {stdout}=await execFile("rg",["-n","\\bTARGET\\b","routes.txt"]);
console.log(stdout);

// Display the complete bundled HTTP serve documentation and its UTF-8 byte length.
// @noe: {"outputBytes": 24000}
import {docs} from "noe:docs";
const detail = docs("noe:http", "serve");
console.log(detail);
console.log("UTF-8 bytes:", new TextEncoder().encode(detail).length);
